INSERT INTO campuses (code, name, short_name, address, phone) VALUES
    ('CS-A', 'Cơ sở 1 – Trường Mầm non Thượng Hồng', 'Cơ sở 1', 'Thôn Ngọc Lâm, xã Thượng Hồng, thành phố Hải Phòng', '02253876125'),
