INSERT INTO rooms (campus_id, code, name, room_type, capacity, status)
SELECT c.id, v.code, v.name, v.room_type, v.capacity::smallint, v.status
FROM (VALUES
    ('CS-A', 'P101', 'Phòng 101', 'CLASS', 25, 'ACTIVE'),
    ('CS-A', 'P102', 'Phòng 102', 'CLASS', 25, 'ACTIVE'),
    ('CS-A', 'P103', 'Phòng 103', 'CLASS', 30, 'ACTIVE'),
    ('CS-A', 'P201', 'Phòng 201', 'CLASS', 35, 'ACTIVE'),
    ('CS-A', 'P202', 'Phòng 202', 'CLASS', 35, 'ACTIVE'),
    ('CS-A', 'BEP', 'Bếp ăn', 'KITCHEN', NULL, 'ACTIVE'),
    ('CS-A', 'KHO', 'Kho thực phẩm khô', 'STORAGE', NULL, 'ACTIVE'),
    ('CS-A', 'YTE', 'Phòng y tế', 'DEPARTMENT', NULL, 'ACTIVE'),
    ('CS-A', 'AMN', 'Phòng âm nhạc', 'FUNCTION_ROOM', 40, 'ACTIVE'),
    ('CS-A', 'P203', 'Phòng 203 (đang sửa chữa)', 'CLASS', 30, 'INACTIVE'),
    ('CS-B', 'P101', 'Phòng 101', 'CLASS', 25, 'ACTIVE'),
    ('CS-B', 'P102', 'Phòng 102', 'CLASS', 25, 'ACTIVE'),
    ('CS-B', 'P103', 'Phòng 103', 'CLASS', 30, 'ACTIVE'),
    ('CS-B', 'P201', 'Phòng 201', 'CLASS', 35, 'ACTIVE'),
    ('CS-B', 'P202', 'Phòng 202', 'CLASS', 35, 'ACTIVE'),
    ('CS-B', 'BEP', 'Bếp ăn', 'KITCHEN', NULL, 'ACTIVE'),
    ('CS-B', 'KHO', 'Kho thực phẩm khô', 'STORAGE', NULL, 'ACTIVE'),
    ('CS-B', 'YTE', 'Phòng y tế', 'DEPARTMENT', NULL, 'ACTIVE'),
    ('CS-B', 'AMN', 'Phòng âm nhạc', 'FUNCTION_ROOM', 40, 'ACTIVE'),
    ('CS-B', 'P203', 'Phòng 203 (đang sửa chữa)', 'CLASS', 30, 'INACTIVE')
) AS v (campus_code, code, name, room_type, capacity, status)
JOIN campuses c ON c.code = v.campus_code
WHERE NOT EXISTS (SELECT 1 FROM rooms r WHERE r.campus_id = c.id AND LOWER(r.code) = LOWER(v.code) AND r.status <> 'DELETED');

INSERT INTO classrooms (campus_id, school_year_id, name, age_group_id, room_id, capacity)
SELECT c.id, (SELECT id FROM school_years WHERE name = '2026-2027'), v.name, g.id, r.id, g.max_class_size
FROM (VALUES
    ('CS-A', 'Lớp Nhà trẻ 1', 'ag-2', 'P101'),
    ('CS-A', 'Lớp Mầm 1', 'ag-3', 'P102'),
    ('CS-A', 'Lớp Chồi 1', 'ag-4', 'P103'),
    ('CS-A', 'Lớp Lá 1', 'ag-5', 'P201'),
    ('CS-A', 'Lớp Lá 2', 'ag-5', 'P202'),
    ('CS-B', 'Lớp Nhà trẻ 2', 'ag-2', 'P101'),
    ('CS-B', 'Lớp Mầm 2', 'ag-3', 'P102'),
    ('CS-B', 'Lớp Chồi 2', 'ag-4', 'P103'),
    ('CS-B', 'Lớp Lá 3', 'ag-5', 'P201'),
    ('CS-B', 'Lớp Lá 4', 'ag-5', 'P202')
) AS v (campus_code, name, age_group_code, room_code)
JOIN campuses c ON c.code = v.campus_code
JOIN age_groups g ON g.code = v.age_group_code
JOIN rooms r ON r.campus_id = c.id AND r.code = v.room_code AND r.status = 'ACTIVE'
ON CONFLICT (school_year_id, campus_id, name) DO NOTHING;

