-- Năm học đang chạy, do Hiệu trưởng kích hoạt trước ngày khai giảng (trừ khi DB đã có năm ACTIVE khác)
UPDATE school_years SET status = 'ACTIVE', activated_at = TIMESTAMPTZ '2026-08-20 09:00+07',
                        activated_by = (SELECT id FROM user_accounts WHERE keycloak_user_id = '00000000-0000-4000-a000-000000000002')
WHERE name = '2026-2027' AND status = 'PLANNED'
  AND NOT EXISTS (SELECT 1 FROM school_years WHERE status = 'ACTIVE');

-- Lịch năm học (ngày học = thứ 2–6 trừ các khoảng nghỉ này; các file seed vận hành dùng chung lịch này)
INSERT INTO school_holidays (school_year_id, start_date, end_date, name)
SELECT (SELECT id FROM school_years WHERE name = '2026-2027'), v.start_date::date, v.end_date::date, v.name
FROM (VALUES
    ('2026-09-01', '2026-09-02', 'Nghỉ lễ Quốc khánh'),
    ('2027-01-01', '2027-01-01', 'Nghỉ Tết Dương lịch'),
    ('2027-02-03', '2027-02-12', 'Nghỉ Tết Nguyên đán Đinh Mùi'),
    ('2027-04-16', '2027-04-16', 'Nghỉ Giỗ Tổ Hùng Vương'),
    ('2027-04-30', '2027-05-01', 'Nghỉ lễ 30/4 và 1/5')
) AS v (start_date, end_date, name)
WHERE NOT EXISTS (SELECT 1 FROM school_holidays h WHERE h.school_year_id = (SELECT id FROM school_years WHERE name = '2026-2027') AND h.start_date = v.start_date::date);

-- Giờ chốt: tuần đầu năm chốt 9 giờ cho phụ huynh quen, từ 14/09 chốt 8 giờ 30
INSERT INTO attendance_cutoffs (school_year_id, cutoff_time, effective_from, note, created_by, created_at)
SELECT (SELECT id FROM school_years WHERE name = '2026-2027'), v.cutoff_time::time, v.effective_from::date, v.note, (SELECT id FROM user_accounts WHERE keycloak_user_id = '00000000-0000-4000-a000-000000000002'), v.created_at::timestamptz
FROM (VALUES
    ('09:00', '2026-09-01', 'Tuần đầu năm học chốt điểm danh và báo ăn trước 9 giờ', '2026-08-25 09:00+07'),
    ('08:30', '2026-09-14', 'Chốt điểm danh và báo ăn trước 8 giờ 30', '2026-09-11 15:00+07')
) AS v (cutoff_time, effective_from, note, created_at)
WHERE NOT EXISTS (SELECT 1 FROM attendance_cutoffs c WHERE c.school_year_id = (SELECT id FROM school_years WHERE name = '2026-2027') AND c.effective_from = v.effective_from::date);

INSERT INTO staff_assignments (user_id, staff_role, campus_id, classroom_id, age_group_id, school_year_id, is_homeroom,
                               valid_from, valid_to, assigned_by, is_substitute, replaced_user_id)
SELECT u.id, v.staff_role, c.id, cl.id, g.id, CASE WHEN v.age_group_code IS NULL THEN NULL ELSE (SELECT id FROM school_years WHERE name = '2026-2027') END, v.homeroom,
       v.valid_from::date, v.valid_to::date, (SELECT id FROM user_accounts WHERE keycloak_user_id = '00000000-0000-4000-a000-000000000002'), v.substitute, ru.id
FROM (VALUES
    ('00000000-0000-4000-a000-000000000002', 'PRINCIPAL', NULL, NULL, NULL, NULL, false, '2026-08-15', NULL, false, NULL),
    ('00000000-0000-4000-a000-000000000003', 'VICE_PRINCIPAL', 'CS-A', NULL, NULL, NULL, false, '2026-08-15', NULL, false, NULL),
    ('00000000-0000-4000-b000-000000000001', 'VICE_PRINCIPAL', 'CS-B', NULL, NULL, NULL, false, '2026-08-15', NULL, false, NULL),
    ('00000000-0000-4000-b000-000000000002', 'TEACHER', NULL, 'CS-A', 'Lớp Nhà trẻ 1', NULL, true, '2026-08-15', NULL, false, NULL),
