    ('00000000-0000-4000-b000-000000000018', 'TEACHER', NULL, 'CS-B', 'Lớp Lá 4', NULL, true, '2026-08-15', NULL, false, NULL),
    ('00000000-0000-4000-b000-000000000019', 'TEACHER', NULL, 'CS-B', 'Lớp Lá 4', NULL, false, '2026-08-15', NULL, false, NULL),
    ('00000000-0000-4000-b000-000000000020', 'TEACHER', NULL, 'CS-A', 'Lớp Lá 1', NULL, false, '2026-08-15', '2026-10-31', false, NULL),
    ('00000000-0000-4000-b000-000000000021', 'TEACHER', NULL, 'CS-B', 'Lớp Mầm 2', NULL, false, '2026-10-12', '2026-10-16', true, '00000000-0000-4000-b000-000000000013'),
    ('00000000-0000-4000-a000-000000000008', 'KITCHEN_STAFF', 'CS-A', NULL, NULL, NULL, false, '2026-08-15', NULL, false, NULL),
    ('00000000-0000-4000-b000-000000000022', 'KITCHEN_STAFF', 'CS-B', NULL, NULL, NULL, false, '2026-08-15', NULL, false, NULL)
) AS v (keycloak_user_id, staff_role, campus_code, class_campus_code, class_name, age_group_code, homeroom, valid_from, valid_to,
        substitute, replaced_keycloak_id)
JOIN user_accounts u ON u.keycloak_user_id = v.keycloak_user_id
LEFT JOIN user_accounts ru ON ru.keycloak_user_id = v.replaced_keycloak_id
LEFT JOIN campuses c ON c.code = v.campus_code
LEFT JOIN campuses cc ON cc.code = v.class_campus_code
LEFT JOIN classrooms cl ON cl.campus_id = cc.id AND cl.name = v.class_name AND cl.school_year_id = (SELECT id FROM school_years WHERE name = '2026-2027')
LEFT JOIN age_groups g ON g.code = v.age_group_code
WHERE NOT EXISTS (
    SELECT 1 FROM staff_assignments a
    WHERE a.user_id = u.id AND a.staff_role = v.staff_role AND a.valid_from = v.valid_from::date
      AND a.campus_id IS NOT DISTINCT FROM c.id AND a.classroom_id IS NOT DISTINCT FROM cl.id
      AND a.age_group_id IS NOT DISTINCT FROM g.id
);

INSERT INTO permission_grants (user_id, permission_code, effect, scope, reason, granted_by)
SELECT u.id, v.permission_code, v.effect, v.scope, v.reason, gb.id
FROM (VALUES
    ('00000000-0000-4000-b000-000000000018', 'CHILD_PROFILE_EDIT', 'GRANT', 'CAMPUS', 'Hỗ trợ Phó hiệu trưởng cập nhật hồ sơ trẻ Cơ sở 2 đầu năm học', '00000000-0000-4000-a000-000000000002'),
    ('00000000-0000-4000-b000-000000000015', 'ASSESSMENT_CONFIRM', 'REVOKE', NULL, 'Giáo viên tập sự, giáo viên chủ nhiệm xác nhận đánh giá thay', '00000000-0000-4000-a000-000000000002'),
    ('00000000-0000-4000-a000-000000000003', 'NUTRITION_MANAGE', 'GRANT', 'SCHOOL', 'Phó hiệu trưởng phụ trách dinh dưỡng quản lý danh mục bán trú toàn trường', '00000000-0000-4000-a000-000000000002'),
    ('00000000-0000-4000-a000-000000000003', 'MENU_MANAGE', 'GRANT', 'SCHOOL', 'Phó hiệu trưởng phụ trách dinh dưỡng lập và công bố thực đơn chung hai cơ sở', '00000000-0000-4000-a000-000000000002'),
    ('00000000-0000-4000-a000-000000000003', 'STOCK_MANAGE', 'GRANT', 'CAMPUS', 'Phó hiệu trưởng nhập kho khô tại cơ sở phụ trách', '00000000-0000-4000-a000-000000000002'),
    ('00000000-0000-4000-a000-000000000003', 'FOOD_SAFETY_APPROVE', 'GRANT', 'CAMPUS', 'Phó hiệu trưởng duyệt lưu mẫu, hủy mẫu thức ăn tại cơ sở phụ trách', '00000000-0000-4000-a000-000000000002'),
    ('00000000-0000-4000-b000-000000000001', 'STOCK_MANAGE', 'GRANT', 'CAMPUS', 'Phó hiệu trưởng nhập kho khô tại cơ sở phụ trách', '00000000-0000-4000-a000-000000000002'),
    ('00000000-0000-4000-b000-000000000001', 'FOOD_SAFETY_APPROVE', 'GRANT', 'CAMPUS', 'Phó hiệu trưởng duyệt lưu mẫu, hủy mẫu thức ăn tại cơ sở phụ trách', '00000000-0000-4000-a000-000000000002')
) AS v (keycloak_user_id, permission_code, effect, scope, reason, granted_by)
JOIN user_accounts u ON u.keycloak_user_id = v.keycloak_user_id
JOIN user_accounts gb ON gb.keycloak_user_id = v.granted_by
WHERE NOT EXISTS (SELECT 1 FROM permission_grants p WHERE p.user_id = u.id AND p.permission_code = v.permission_code);

-- Lịch sử đổi quyền tương ứng (màn lịch sử phân quyền): trước đó kế thừa vai trò
INSERT INTO permission_change_log (batch_id, actor_user_id, target_user_id, permission_code, before_state, after_state,
                                   after_scope, reason, changed_at)
SELECT md5('perm:' || p.user_id || ':' || p.permission_code)::uuid, p.granted_by, p.user_id, p.permission_code, 'INHERIT',
       p.effect, p.scope, p.reason, TIMESTAMPTZ '2026-09-10 14:00+07'
FROM permission_grants p
WHERE p.user_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM permission_change_log l WHERE l.target_user_id = p.user_id AND l.permission_code = p.permission_code);

